commands.command:
set -eu
sudo -n tee /etc/named.conf >/dev/null <<'ANTRIEB_NAMED_CONF'
options {
    listen-on port 53 { 127.0.0.1; 10.100.165.10; };
    listen-on-v6 port 53 { none; };
    directory "/var/named";
    dump-file "/var/named/data/cache_dump.db";
    statistics-file "/var/named/data/named_stats.txt";
    memstatistics-file "/var/named/data/named_mem_stats.txt";
    secroots-file "/var/named/data/named.secroots";
    recursing-file "/var/named/data/named.recursing";
    allow-query { any; };
    recursion no;
    dnssec-validation yes;
    managed-keys-directory "/var/named/dynamic";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
};

logging {
    channel default_debug {
        file "data/named.run";
        severity dynamic;
    };
};

include "/etc/named/infra-update.key";

zone "infra.test" IN {
    type master;
    file "dynamic/infra.test.db";
    allow-update { key infra-update; };
    allow-transfer { 10.100.165.11; 10.100.165.12; };
    also-notify { 10.100.165.11; 10.100.165.12; };
    notify yes;
    inline-signing yes;
    dnssec-policy default;
};
ANTRIEB_NAMED_CONF
sudo -n tee /var/named/dynamic/infra.test.db >/dev/null <<'ANTRIEB_ZONE'
$TTL 300
@ IN SOA ns1.infra.test. hostmaster.infra.test. (
    2026090101
    60
    30
    604800
    60
)
@      IN NS  ns1.infra.test.
@      IN NS  ns2.infra.test.
@      IN NS  ns3.infra.test.
ns1    IN A   10.100.165.10
ns2    IN A   10.100.165.11
ns3    IN A   10.100.165.12
app    IN A   10.100.165.10
status IN TXT "ready"
ANTRIEB_ZONE
sudo -n chown root:named /etc/named.conf
sudo -n chmod 0640 /etc/named.conf
sudo -n chown named:named /var/named/dynamic/infra.test.db
sudo -n chmod 0660 /var/named/dynamic/infra.test.db
sudo -n restorecon -RF /etc/named.conf /var/named/dynamic
sudo -n stat -c '%n %U:%G %a %s' /etc/named.conf /var/named/dynamic/infra.test.db

